import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken Breast", "Brown Rice", "Tofu", "Spinach", "Almonds", "Salmon"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Chicken Breast": 4,
        "Brown Rice": 10,
        "Tofu": 6,
        "Spinach": 1,
        "Almonds": 8,
        "Salmon": 6,
    },
    "content": {
        # nutrient: {food: grams/units per serving}
        "protein": {
            "Chicken Breast": 14,
            "Brown Rice": 11,
            "Tofu": 20,
            "Spinach": 6,
            "Almonds": 9,
            "Salmon": 20,
        },
        "carbs": {
            "Chicken Breast": 4,
            "Brown Rice": 17,
            "Tofu": 12,
            "Spinach": 20,
            "Almonds": 11,
            "Salmon": 19,
        },
        "calories": {
            "Chicken Breast": 275,
            "Brown Rice": 151,
            "Tofu": 155,
            "Spinach": 106,
            "Almonds": 279,
            "Salmon": 93,
        },
    },
    "requirement": {
        "protein": 78,
        "carbs": 140,
        "calories": 1537,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.servings = pyo.Var(model.F, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.F)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.servings[f] for f in m.F) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
